def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    recent = history[-10:]
    opp_dr = 0
    for m, o in recent:
        if o == 'D':
            opp_dr += 1

    opp_c_recent = len(recent) - opp_dr

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    if opp_dr >= 6 or (opp_d >= 10 and opp_dr >= 4):
        return 'D'

    if last_opp == 'C':
        return 'C'

    if opp_streak >= 3:
        return 'D'

    if my_d > opp_d + 2 and opp_d <= 3 and opp_dr <= 3 and opp_c_recent >= 3:
        return 'C'

    if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C' and last_my == 'C' and last_opp == 'D' and opp_dr <= 3 and opp_d <= 6:
        return 'C'

    if last_my == 'D' and last_opp == 'D' and opp_streak == 2 and opp_d <= 4 and opp_c_recent >= 2:
        return 'C'

    if last_my == 'C':
        return 'D'

    if opp_d <= 3 and opp_dr <= 2 and opp_c_recent >= 5:
        return 'C'

    return 'D'
